20	import * as zrUtil from 'zrender/src/core/util';
21	import ChartView from '../../view/Chart';
22	import * as graphic from '../../util/graphic';
23	import { setStatesStylesFromModel } from '../../util/states';
24	import Path, { PathProps } from 'zrender/src/graphic/Path';
25	import {createClipPath} from '../helper/createClipPathFromCoordSys';
26	import CandlestickSeriesModel, { CandlestickDataItemOption } from './CandlestickSeries';
27	import GlobalModel from '../../model/Global';
28	import ExtensionAPI from '../../core/ExtensionAPI';
29	import { StageHandlerProgressParams } from '../../util/types';
30	import SeriesData from '../../data/SeriesData';
31	import {CandlestickItemLayout} from './candlestickLayout';
32	import { CoordinateSystemClipArea } from '../../coord/CoordinateSystem';
33	import Model from '../../model/Model';
34	import { saveOldStyle } from '../../animation/basicTransition';
35	import Element from 'zrender/src/Element';
36	
37	const SKIP_PROPS = ['color', 'borderColor'] as const;
38	
39	class CandlestickView extends ChartView {
40	
41	    static readonly type = 'candlestick';
42	    readonly type = CandlestickView.type;
43	
44	    private _isLargeDraw: boolean;
45	
46	    private _data: SeriesData;
47	
48	    private _progressiveEls: Element[];
49	
50	    render(seriesModel: CandlestickSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
51	        // If there is clipPath created in large mode. Remove it.
52	        this.group.removeClipPath();
53	        // Clear previously rendered progressive elements.
54	        this._progressiveEls = null;
55	
56	        this._updateDrawMode(seriesModel);
57	
58	        this._isLargeDraw
59	            ? this._renderLarge(seriesModel)
60	            : this._renderNormal(seriesModel);
61	    }
62	
63	    incrementalPrepareRender(seriesModel: CandlestickSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
64	        this._clear();
65	        this._updateDrawMode(seriesModel);
66	    }
67	
68	    incrementalRender(
69	        params: StageHandlerProgressParams,
70	        seriesModel: CandlestickSeriesModel,
71	        ecModel: GlobalModel,
72	        api: ExtensionAPI
73	    ) {
74	        this._progressiveEls = [];
75	        this._isLargeDraw
76	             ? this._incrementalRenderLarge(params, seriesModel)
77	             : this._incrementalRenderNormal(params, seriesModel);
78	    }
79	
80	    eachRendered(cb: (el: Element) => boolean | void) {
81	        graphic.traverseElements(this._progressiveEls || this.group, cb);
82	    }
83	
84	    _updateDrawMode(seriesModel: CandlestickSeriesModel) {
85	        const isLargeDraw = seriesModel.pipelineContext.large;
86	        if (this._isLargeDraw == null || isLargeDraw !== this._isLargeDraw) {
87	            this._isLargeDraw = isLargeDraw;
88	            this._clear();
89	        }
90	    }
91	
92	    _renderNormal(seriesModel: CandlestickSeriesModel) {
93	        const data = seriesModel.getData();
94	        const oldData = this._data;
95	        const group = this.group;
96	        const isSimpleBox = data.getLayout('isSimpleBox');
97	
98	        const needsClip = seriesModel.get('clip', true);
99	        const coord = seriesModel.coordinateSystem;
100	        const clipArea = coord.getArea && coord.getArea();
101	
102	        // There is no old data only when first rendering or switching from
103	        // stream mode to normal mode, where previous elements should be removed.
104	        if (!this._data) {
105	            group.removeAll();
106	        }
107	
108	        data.diff(oldData)
109	            .add(function (newIdx) {
110	                if (data.hasValue(newIdx)) {
111	                    const itemLayout = data.getItemLayout(newIdx) as CandlestickItemLayout;
112	
113	                    if (needsClip && isNormalBoxClipped(clipArea, itemLayout)) {
114	                        return;
115	                    }
116	
117	                    const el = createNormalBox(itemLayout, newIdx, true);
118	                    graphic.initProps(el, {shape: {points: itemLayout.ends}}, seriesModel, newIdx);
119	
120	                    setBoxCommon(el, data, newIdx, isSimpleBox);
121	
122	                    group.add(el);
123	
124	                    data.setItemGraphicEl(newIdx, el);
125	                }
126	            })
127	            .update(function (newIdx, oldIdx) {
128	                let el = oldData.getItemGraphicEl(oldIdx) as NormalBoxPath;
129	
130	                // Empty data
131	                if (!data.hasValue(newIdx)) {
132	                    group.remove(el);
133	                    return;
134	                }
135	
136	                const itemLayout = data.getItemLayout(newIdx) as CandlestickItemLayout;
137	                if (needsClip && isNormalBoxClipped(clipArea, itemLayout)) {
138	                    group.remove(el);
139	                    return;
140	                }
141	
142	                if (!el) {
143	                    el = createNormalBox(itemLayout, newIdx);
144	                }
145	                else {
146	                    graphic.updateProps(el, {
147	                        shape: {
148	                            points: itemLayout.ends
149	                        }
150	                    }, seriesModel, newIdx);
151	
152	                    saveOldStyle(el);
153	                }
154	
155	                setBoxCommon(el, data, newIdx, isSimpleBox);
156	
157	                group.add(el);
158	                data.setItemGraphicEl(newIdx, el);
159	            })
160	            .remove(function (oldIdx) {
161	                const el = oldData.getItemGraphicEl(oldIdx);
162	                el && group.remove(el);
163	            })
164	            .execute();
165	
166	        this._data = data;
167	    }
168	
169	    _renderLarge(seriesModel: CandlestickSeriesModel) {
170	        this._clear();
171	
172	        createLarge(seriesModel, this.group);
173	
174	        const clipPath = seriesModel.get('clip', true)
175	            ? createClipPath(seriesModel.coordinateSystem, false, seriesModel)
176	            : null;
177	        if (clipPath) {
178	            this.group.setClipPath(clipPath);
179	        }
180	        else {
181	            this.group.removeClipPath();
182	        }
183	
184	    }
185	
186	    _incrementalRenderNormal(params: StageHandlerProgressParams, seriesModel: CandlestickSeriesModel) {
187	        const data = seriesModel.getData();
188	        const isSimpleBox = data.getLayout('isSimpleBox');
189	
190	        let dataIndex;
191	        while ((dataIndex = params.next()) != null) {
192	            const itemLayout = data.getItemLayout(dataIndex) as CandlestickItemLayout;
193	            const el = createNormalBox(itemLayout, dataIndex);
194	            setBoxCommon(el, data, dataIndex, isSimpleBox);
195	
196	            el.incremental = true;
197	            this.group.add(el);
198	
199	            this._progressiveEls.push(el);
200	        }
201	    }
202	
203	    _incrementalRenderLarge(params: StageHandlerProgressParams, seriesModel: CandlestickSeriesModel) {
204	        createLarge(seriesModel, this.group, this._progressiveEls, true);
205	    }
206	
207	    remove(ecModel: GlobalModel) {
208	        this._clear();
209	    }
210	
211	    _clear() {
212	        this.group.removeAll();
213	        this._data = null;
214	    }
215	}
216	
217	class NormalBoxPathShape {
218	    points: number[][];
219	}
220	
221	interface NormalBoxPathProps extends PathProps {
222	    shape?: Partial<NormalBoxPathShape>
223	}
224	
225	class NormalBoxPath extends Path<NormalBoxPathProps> {
226	
227	    readonly type = 'normalCandlestickBox';
228	
229	    shape: NormalBoxPathShape;
230	
231	    __simpleBox: boolean;
232	
233	    constructor(opts?: NormalBoxPathProps) {
234	        super(opts);
235	    }
236	
237	    getDefaultShape() {
238	        return new NormalBoxPathShape();
239	    }
240	
241	    buildPath(ctx: CanvasRenderingContext2D, shape: NormalBoxPathShape) {
242	        const ends = shape.points;
243	
244	        if (this.__simpleBox) {
245	            ctx.moveTo(ends[4][0], ends[4][1]);
246	            ctx.lineTo(ends[6][0], ends[6][1]);
247	        }
248	        else {
249	            ctx.moveTo(ends[0][0], ends[0][1]);
250	            ctx.lineTo(ends[1][0], ends[1][1]);
251	            ctx.lineTo(ends[2][0], ends[2][1]);
252	            ctx.lineTo(ends[3][0], ends[3][1]);
253	            ctx.closePath();
254	
255	            ctx.moveTo(ends[4][0], ends[4][1]);
256	            ctx.lineTo(ends[5][0], ends[5][1]);
257	            ctx.moveTo(ends[6][0], ends[6][1]);
258	            ctx.lineTo(ends[7][0], ends[7][1]);
259	        }
260	    }
261	}
262	
263	
264	function createNormalBox(itemLayout: CandlestickItemLayout, dataIndex: number, isInit?: boolean) {
265	    const ends = itemLayout.ends;
266	    return new NormalBoxPath({
267	        shape: {
268	            points: isInit
269	                ? transInit(ends, itemLayout)
270	                : ends
271	        },
272	        z2: 100
273	    });
274	}
275	
276	function isNormalBoxClipped(clipArea: CoordinateSystemClipArea, itemLayout: CandlestickItemLayout) {
277	    let clipped = true;
278	    for (let i = 0; i < itemLayout.ends.length; i++) {
279	        // If any point are in the region.
280	        if (clipArea.contain(itemLayout.ends[i][0], itemLayout.ends[i][1])) {
281	            clipped = false;
282	            break;
283	        }
284	    }
285	    return clipped;
286	}
287	
288	function setBoxCommon(el: NormalBoxPath, data: SeriesData, dataIndex: number, isSimpleBox?: boolean) {
289	    const itemModel = data.getItemModel(dataIndex) as Model<CandlestickDataItemOption>;
290	
291	    el.useStyle(data.getItemVisual(dataIndex, 'style'));
292	    el.style.strokeNoScale = true;
293	
294	    el.__simpleBox = isSimpleBox;
295	
296	    setStatesStylesFromModel(el, itemModel);
297	}
298	
299	function transInit(points: number[][], itemLayout: CandlestickItemLayout) {
300	    return zrUtil.map(points, function (point) {
301	        point = point.slice();
302	        point[1] = itemLayout.initBaseline;
303	        return point;
304	    });
305	}
306	
307	
308	
309	class LargeBoxPathShape {
310	    points: ArrayLike<number>;
311	}
312	
313	interface LargeBoxPathProps extends PathProps {
314	    shape?: Partial<LargeBoxPathShape>
315	    __sign?: number
316	}
317	
318	class LargeBoxPath extends Path {
319	    readonly type = 'largeCandlestickBox';
320	
321	    shape: LargeBoxPathShape;
322	
323	    __sign: number;
324	
325	    constructor(opts?: LargeBoxPathProps) {
326	        super(opts);
327	    }
328	
329	    getDefaultShape() {
330	        return new LargeBoxPathShape();
331	    }
332	
333	    buildPath(ctx: CanvasRenderingContext2D, shape: LargeBoxPathShape) {
334	        // Drawing lines is more efficient than drawing
335	        // a whole line or drawing rects.
336	        const points = shape.points;
337	        for (let i = 0; i < points.length;) {
338	            if (this.__sign === points[i++]) {
339	                const x = points[i++];
340	                ctx.moveTo(x, points[i++]);
341	                ctx.lineTo(x, points[i++]);
342	            }
343	            else {
344	                i += 3;
345	            }
346	        }
347	    }
348	}
349	
350	function createLarge(
351	    seriesModel: CandlestickSeriesModel,
352	    group: graphic.Group,
353	    progressiveEls?: Element[],
354	    incremental?: boolean
355	) {
356	    const data = seriesModel.getData();
357	    const largePoints = data.getLayout('largePoints');
358	
359	    const elP = new LargeBoxPath({
360	        shape: {points: largePoints},
361	        __sign: 1,
362	        ignoreCoarsePointer: true
363	    });
364	    group.add(elP);
365	    const elN = new LargeBoxPath({
366	        shape: {points: largePoints},
367	        __sign: -1,
368	        ignoreCoarsePointer: true
369	    });
370	    group.add(elN);
371	    const elDoji = new LargeBoxPath({
372	        shape: {points: largePoints},
373	        __sign: 0,
374	        ignoreCoarsePointer: true
375	    });
376	    group.add(elDoji);
377	
378	    setLargeStyle(1, elP, seriesModel, data);
379	    setLargeStyle(-1, elN, seriesModel, data);
380	    setLargeStyle(0, elDoji, seriesModel, data);
381	
382	    if (incremental) {
383	        elP.incremental = true;
384	        elN.incremental = true;
385	    }
386	
387	    if (progressiveEls) {
388	        progressiveEls.push(elP, elN);
389	    }
390	}
391	
392	function setLargeStyle(sign: number, el: LargeBoxPath, seriesModel: CandlestickSeriesModel, data: SeriesData) {
393	    // TODO put in visual?
394	    let borderColor = seriesModel.get(['itemStyle', sign > 0 ? 'borderColor' : 'borderColor0'])
395	        // Use color for border color by default.
396	        || seriesModel.get(['itemStyle', sign > 0 ? 'color' : 'color0']);
397	    if (sign === 0) {
398	        borderColor = seriesModel.get(['itemStyle', 'borderColorDoji']);
399	    }
400	
401	    // Color must be excluded.
402	    // Because symbol provide setColor individually to set fill and stroke
403	    const itemStyle = seriesModel.getModel('itemStyle').getItemStyle(SKIP_PROPS);
404	
405	    el.useStyle(itemStyle);
406	    el.style.fill = null;
407	    el.style.stroke = borderColor;
408	}
409	
410	
411	
412	export default CandlestickView;
