20	import createRenderPlanner from '../helper/createRenderPlanner';
21	import { StageHandler } from '../../util/types';
22	import CandlestickSeriesModel, { CandlestickDataItemOption } from './CandlestickSeries';
23	import Model from '../../model/Model';
24	import { extend } from 'zrender/src/core/util';
25	
26	const positiveBorderColorQuery = ['itemStyle', 'borderColor'] as const;
27	const negativeBorderColorQuery = ['itemStyle', 'borderColor0'] as const;
28	const dojiBorderColorQuery = ['itemStyle', 'borderColorDoji'] as const;
29	const positiveColorQuery = ['itemStyle', 'color'] as const;
30	const negativeColorQuery = ['itemStyle', 'color0'] as const;
31	
32	const candlestickVisual: StageHandler = {
33	
34	    seriesType: 'candlestick',
35	
36	    plan: createRenderPlanner(),
37	
38	    // For legend.
39	    performRawSeries: true,
40	
41	    reset: function (seriesModel: CandlestickSeriesModel, ecModel) {
42	
43	        function getColor(sign: number, model: Model<Pick<CandlestickDataItemOption, 'itemStyle'>>) {
44	            return model.get(
45	                sign > 0 ? positiveColorQuery : negativeColorQuery
46	            );
47	        }
48	
49	        function getBorderColor(sign: number, model: Model<Pick<CandlestickDataItemOption, 'itemStyle'>>) {
50	            return model.get(
51	                sign === 0 ? dojiBorderColorQuery
52	                    : sign > 0
53	                        ? positiveBorderColorQuery
54	                        : negativeBorderColorQuery
55	            );
56	        }
57	
58	        // Only visible series has each data be visual encoded
59	        if (ecModel.isSeriesFiltered(seriesModel)) {
60	            return;
61	        }
62	
63	        const isLargeRender = seriesModel.pipelineContext.large;
64	        return !isLargeRender && {
65	            progress(params, data) {
66	                let dataIndex;
67	                while ((dataIndex = params.next()) != null) {
68	                    const itemModel = data.getItemModel(dataIndex);
69	                    const sign = data.getItemLayout(dataIndex).sign;
70	
71	                    const style = itemModel.getItemStyle();
72	                    style.fill = getColor(sign, itemModel);
73	                    style.stroke = getBorderColor(sign, itemModel) || style.fill;
74	
75	                    const existsStyle = data.ensureUniqueItemVisual(dataIndex, 'style');
76	                    extend(existsStyle, style);
77	                }
78	            }
79	        };
80	
81	
82	    }
83	
84	};
85	
86	export default candlestickVisual;
