import { EChartsType } from '@/src/echarts';
import { createChart, getECModel } from '../../../core/utHelper';
import { CandlestickSeriesOption } from '@/src/chart/candlestick/CandlestickSeries';
import Displayable from 'zrender/src/graphic/Displayable';
import { getECData } from '@/src/util/innerStore';

function makeOption(extra?: Partial<CandlestickSeriesOption>): any {
    return {
        animation: false,
        xAxis: {
            data: ['2017-10-24', '2017-10-25', '2017-10-26', '2017-10-27']
        },
        yAxis: {},
        series: [Object.assign({
            type: 'candlestick' as const,
            large: false,
            data: [
                // close > open --> sign 1 (positive)
                [20, 34, 10, 38],
                // close < open --> sign -1 (negative)
                [40, 35, 30, 50],
                [31, 38, 28, 44],
                [38, 15, 5, 42]
            ]
        }, extra)]
    };
}

function getBoxes(chart: EChartsType): Displayable[] {
    const seriesModel = getECModel(chart).getSeriesByIndex(0);
    const els: Displayable[] = [];
    seriesModel.getData().eachItemGraphicEl(function (el) {
        els.push(el as unknown as Displayable);
    });
    return els;
}

describe('candlestick_states', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should create emphasis / blur / select states on the box elements', function () {
        chart.setOption(makeOption());
        const boxes = getBoxes(chart);
        expect(boxes.length).toBe(4);
        expect(boxes[0].states.emphasis).toBeTruthy();
        expect(boxes[0].states.blur).toBeTruthy();
        expect(boxes[0].states.select).toBeTruthy();
        // Default emphasis itemStyle.borderWidth is 2.
        expect(boxes[0].states.emphasis.style.lineWidth).toBe(2);
        // Enabled as a highlight / downplay dispatcher so that
        // mouseover triggers the emphasis state.
        expect((boxes[0] as any).__highDownDispatcher).toBe(true);
    });

    it('should resolve emphasis color / color0 and borderColor / borderColor0 by sign', function () {
        chart.setOption(makeOption({
            emphasis: {
                focus: 'self',
                itemStyle: {
                    color: 'purple',
                    borderColor: 'cyan',
                    color0: 'blue',
                    borderColor0: 'brown'
                }
            }
        }));
        const boxes = getBoxes(chart);

        // Positive box.
        expect(boxes[0].states.emphasis.style.fill).toBe('purple');
        expect(boxes[0].states.emphasis.style.stroke).toBe('cyan');
        // Negative box.
        expect(boxes[1].states.emphasis.style.fill).toBe('blue');
        expect(boxes[1].states.emphasis.style.stroke).toBe('brown');

        // focus is honoured.
        expect(getECData(boxes[0]).focus).toBe('self');
    });

    it('should resolve blur color / color0 by sign', function () {
        chart.setOption(makeOption({
            blur: {
                itemStyle: {
                    color: 'grey',
                    borderColor: 'pink',
                    color0: 'gray',
                    borderColor0: 'orange'
                }
            }
        }));
        const boxes = getBoxes(chart);
        expect(boxes[0].states.blur.style.fill).toBe('grey');
        expect(boxes[0].states.blur.style.stroke).toBe('pink');
        expect(boxes[1].states.blur.style.fill).toBe('gray');
        expect(boxes[1].states.blur.style.stroke).toBe('orange');
    });

    it('should fall back to the state color when the state border color is not given', function () {
        chart.setOption(makeOption({
            emphasis: {
                itemStyle: {
                    color: 'purple',
                    color0: 'blue'
                }
            }
        }));
        const boxes = getBoxes(chart);
        expect(boxes[0].states.emphasis.style.stroke).toBe('purple');
        expect(boxes[1].states.emphasis.style.stroke).toBe('blue');
    });

    it('should not disturb the normal style', function () {
        chart.setOption(makeOption({
            emphasis: {
                itemStyle: {
                    color: 'purple',
                    borderColor: 'cyan',
                    color0: 'blue',
                    borderColor0: 'brown'
                }
            }
        }));
        const boxes = getBoxes(chart);
        expect(boxes[0].style.fill).toBe('#eb5454');
        expect(boxes[0].style.stroke).toBe('#eb5454');
        expect(boxes[1].style.fill).toBe('#47b262');
        expect(boxes[1].style.stroke).toBe('#47b262');
    });

    it('should not enable the hover dispatcher when emphasis is disabled', function () {
        chart.setOption(makeOption({
            emphasis: {
                disabled: true
            }
        }));
        const boxes = getBoxes(chart);
        expect((boxes[0] as any).__highDownDispatcher).toBeFalsy();
    });
});
